#include "interpolated_region.hpp"
#include <iostream>
#include <unistd.h>
Evaluation reference_objective(const std::vector<Pair>&,const M4&,double,bool,bool);
void require(bool b,const char*s){if(!b)throw std::runtime_error(s);}
double oracle(const std::vector<Pair>&pairs,const M4&T){double total=0;for(auto&p:pairs){auto raw=interpolated(p);auto uv=project(p,T);double value=0;for(auto u:uv){double d=exterior_distance(raw,u),g=d*d/(1+d*d),m=.5+std::atan(d)/M_PI;value+=g*m*m;}total+=value/(uv.size()*pairs.size());}return total;}
int main(int argc,char**argv){try{alarm(30);require(argc==4||argc==5,"args");require(!fs::exists(argv[3]),"exists");double mergedError=0;for(int code=1;code<16;++code){Pair p;p.mask=cv::Mat::zeros(2,2,CV_8U);p.mask.at<uint8_t>(0,0)=code&1;p.mask.at<uint8_t>(0,1)=code&2;p.mask.at<uint8_t>(1,1)=code&4;p.mask.at<uint8_t>(1,0)=code&8;auto raw=interpolated(p);prepare_interpolated_region(p);for(int y=-5;y<20;++y)for(int x=-5;x<20;++x){V2 u(x*.1,y*.1);double old=exterior_distance(raw,u),now=region_inside(p,u)?0:std::sqrt(std::expm1(region_cost(p,u).first));mergedError=std::max(mergedError,std::abs(old-now));}for(int y=0;y<2;++y)for(int x=0;x<2;++x)require(region_inside(p,{double(x),double(y)})==bool(p.mask.at<uint8_t>(y,x)),"label center");}require(mergedError<1e-12,"collinear merging");auto data=load_data(argv[1],std::stoi(argv[2]));M4 T=initialize(data.pairs);double b=1;json fit;if(argc==5){fit=read_json(argv[4]);T=matrix(fit["solve"]["matrix"]);b=fit["solve"]["scalePixels"];prepare_support(data.pairs,matrix(fit["solve"]["stages"][0]["matrix"]));}else prepare_support(data.pairs,T);auto old=reference_objective(data.pairs,T,b,true,true),coarse=objective(data.pairs,T,b,true,true);require(old.geometry==coarse.geometry&&(old.gradient-coarse.gradient).isZero(0),"coarse changed");auto e=objective(data.pairs,T,b,false,true);require(e.value==objective(data.pairs,T,b,false,false).value,"scalar mismatch");double oracleError=std::abs(oracle(data.pairs,T)-e.geometry);require(oracleError<1e-12,"raw segment oracle");if(argc==5)require(std::abs(e.value-fit["solve"]["loss"].get<double>())<1e-12,"savedloss");double worst=0;for(int state=0;state<3;++state){Vec7 offset=Vec7::Zero();if(state==1){offset[0]=1e-4;offset[4]=1e-3;}if(state==2){offset[2]=-2e-4;offset[3]=-1e-3;}M4 pose=delta(offset)*T;auto scored=objective(data.pairs,pose,b,false,true);for(int axis=0;axis<7;++axis){double h=1e-6;Vec7 step=Vec7::Zero();step[axis]=h*units[axis];double plus=objective(data.pairs,delta(step)*pose,b*std::exp(step[6]),false,false).value,minus=objective(data.pairs,delta(-step)*pose,b*std::exp(-step[6]),false,false).value;double fd=(plus-minus)/(2*h);worst=std::max(worst,std::abs(fd-scored.gradient[axis])/(1+std::abs(fd)));}}require(worst<1e-5,"full fine7DFD");double coarsePixelAudit=audit_pixels(data.pairs,T,b);verify_sources(data.provenance);json report={{"passed",true},{"referenceRead",false},{"coarseExactlyUnchanged",true},{"rawSegmentOracleError",oracleError},{"collinearMergingDistanceError",mergedError},{"fullFineSevenCoordinateFDError",worst},{"originalPixelProbabilityAudit",coarsePixelAudit},{"originalPixelAuditScope","retained finite-mask probability only; not interpolated region"},{"finalSavedStateChecked",argc==5}};std::ofstream(argv[3])<<report.dump(2);std::cout<<report.dump()<<std::endl;}catch(std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
